{
  "name": "crypto-dashboard-backend",
  "version": "1.0.0",
  "description": "Express backend for Crypto Trading Dashboard",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "cors": "^2.8.5",
    "axios": "^1.6.0",
