require('dotenv').config({ path: '../.env' });
const express = require('express');
const cors = require('cors');
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

const app = express();
const PORT = process.env.PORT || 5000;
const WATCHLIST_FILE = path.join(__dirname, '..', process.env.WATCHLIST_FILE_PATH || 'watchlist.json');

// Middleware
app.use(cors({ origin: process.env.CORS_ORIGIN || 'http://localhost:3000' }));
app.use(express.json());

// Request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Rate limit tracking for NewsAPI
let newsRequestCount = 0;
let newsResetTime = null;

function resetNewsRateLimit() {
  const now = new Date();
  const nextMidnight = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1, 0, 0, 0, 0));

  if (!newsResetTime || now >= new Date(newsResetTime)) {
    newsRequestCount = 0;
    newsResetTime = nextMidnight.toISOString();
  }
}

// Initialize watchlist file if it doesn't exist
async function initializeWatchlist() {
  try {
    await fs.access(WATCHLIST_FILE);
  } catch {
    const defaultWatchlist = {
      assets: ['BTC', 'ETH', 'SOL'],
      lastUpdated: new Date().toISOString()
    };
    await fs.writeFile(WATCHLIST_FILE, JSON.stringify(defaultWatchlist, null, 2));
    console.log('Initialized watchlist.json with default assets');
  }
}

// Watchlist routes
app.get('/api/watchlist', async (req, res) => {
  try {
    const data = await fs.readFile(WATCHLIST_FILE, 'utf8');
    const watchlist = JSON.parse(data);
    res.json({
      success: true,
      data: watchlist,
      error: null
    });
  } catch (error) {
    console.error('Error reading watchlist:', error);
    res.status(500).json({
      success: false,
      data: null,
      error: {
        code: 'watchlist_read_error',
        message: 'Failed to read watchlist',
        details: { error: error.message }
      }
    });
  }
});

app.post('/api/watchlist', async (req, res) => {
  try {
    const { asset } = req.body;

    // Validation
    if (!asset || typeof asset !== 'string') {
      return res.status(400).json({
        success: false,
        data: null,
        error: {
          code: 'validation_error',
          message: 'Asset symbol is required',
          details: { field: 'asset' }
        }
      });
    }

    const symbol = asset.toUpperCase().trim();
    if (!/^[A-Z]{2,10}$/.test(symbol)) {
      return res.status(400).json({
        success: false,
        data: null,
        error: {
          code: 'validation_error',
          message: 'Asset symbol must be 2-10 uppercase letters',
          details: { field: 'asset', value: asset }
        }
      });
    }

    // Read current watchlist
    const data = await fs.readFile(WATCHLIST_FILE, 'utf8');
    const watchlist = JSON.parse(data);

    // Check for duplicates
    if (watchlist.assets.includes(symbol)) {
      return res.status(400).json({
        success: false,
        data: null,
        error: {
          code: 'duplicate_asset',
          message: `${symbol} is already in your watchlist`,
          details: { asset: symbol }
        }
      });
    }

    // Check max limit
    if (watchlist.assets.length >= 50) {
      return res.status(400).json({
        success: false,
        data: null,
        error: {
          code: 'watchlist_limit_exceeded',
          message: 'Watchlist is full (max 50 assets)',
          details: { currentCount: watchlist.assets.length }
        }
      });
    }

    // Add asset
    watchlist.assets.push(symbol);
    watchlist.lastUpdated = new Date().toISOString();

    await fs.writeFile(WATCHLIST_FILE, JSON.stringify(watchlist, null, 2));

    res.json({
      success: true,
      data: watchlist,
      error: null
    });
  } catch (error) {
    console.error('Error adding to watchlist:', error);
    res.status(500).json({
      success: false,
      data: null,
      error: {
        code: 'watchlist_write_error',
        message: 'Failed to add asset to watchlist',
        details: { error: error.message }
      }
    });
  }
});

app.delete('/api/watchlist/:asset', async (req, res) => {
  try {
    const symbol = req.params.asset.toUpperCase();

    // Read current watchlist
    const data = await fs.readFile(WATCHLIST_FILE, 'utf8');
    const watchlist = JSON.parse(data);

    // Check if asset exists
    const index = watchlist.assets.indexOf(symbol);
    if (index === -1) {
      return res.status(400).json({
        success: false,
        data: null,
        error: {
          code: 'asset_not_found',
          message: `${symbol} is not in your watchlist`,
          details: { asset: symbol }
        }
      });
    }

    // Remove asset
    watchlist.assets.splice(index, 1);
    watchlist.lastUpdated = new Date().toISOString();

    await fs.writeFile(WATCHLIST_FILE, JSON.stringify(watchlist, null, 2));

    res.json({
      success: true,
      data: watchlist,
      error: null
    });
  } catch (error) {
    console.error('Error removing from watchlist:', error);
    res.status(500).json({
      success: false,
      data: null,
      error: {
        code: 'watchlist_write_error',
        message: 'Failed to remove asset from watchlist',
        details: { error: error.message }
      }
    });
  }
});

// Market data route (CoinGecko)
app.get('/api/market/:asset', async (req, res) => {
  try {
    const symbol = req.params.asset.toLowerCase();

    // Map common symbols to CoinGecko IDs
    const symbolMap = {
      btc: 'bitcoin',
      eth: 'ethereum',
      sol: 'solana',
      doge: 'dogecoin',
      ada: 'cardano',
      dot: 'polkadot',
      matic: 'matic-network',
      link: 'chainlink',
      avax: 'avalanche-2',
      atom: 'cosmos'
    };

    const coinId = symbolMap[symbol] || symbol;

    // Fetch OHLCV data (24 hours of 1-hour candles)
    const response = await axios.get(
      `${process.env.COINGECKO_BASE_URL}/coins/${coinId}/ohlc`,
      {
        params: {
          vs_currency: 'usd',
          days: 1
        },
        timeout: 10000
      }
    );

    // Transform data to our format
    const ohlcv = response.data.map(candle => ({
      timestamp: candle[0],
      open: candle[1],
      high: candle[2],
      low: candle[3],
      close: candle[4],
      volume: null // CoinGecko OHLC endpoint doesn't return volume
    }));

    res.json({
      success: true,
      data: {
        asset: req.params.asset.toUpperCase(),
        interval: '1h',
        ohlcv: ohlcv,
        fetchedAt: new Date().toISOString()
      },
      error: null
    });
  } catch (error) {
    console.error('Error fetching market data:', error.message);

    if (error.response && error.response.status === 404) {
      return res.status(404).json({
        success: false,
        data: null,
        error: {
          code: 'asset_not_found',
          message: `Asset ${req.params.asset} not found or not supported`,
          details: { asset: req.params.asset }
        }
      });
    }

    res.status(503).json({
      success: false,
      data: null,
      error: {
        code: 'external_api_unavailable',
        message: 'Market data is temporarily unavailable. Please try again later.',
        details: { error: error.message }
      }
    });
  }
});

// News route (NewsAPI)
app.get('/api/news/:asset', async (req, res) => {
  try {
    resetNewsRateLimit();

    // Check rate limit
    if (newsRequestCount >= 100) {
      return res.status(429).json({
        success: false,
        data: null,
        error: {
          code: 'newsapi_rate_limit_exceeded',
          message: 'Daily news limit reached. The news service allows 100 requests per day (UTC).',
          details: {
            requestsUsedToday: newsRequestCount,
            requestsRemaining: 0,
            resetTime: newsResetTime
          }
        }
      });
    }

    const asset = req.params.asset.toUpperCase();
    const searchQuery = `${asset} OR ${getFullName(asset)} cryptocurrency`;

    // Fetch news from NewsAPI
    const response = await axios.get(
      `${process.env.NEWS_API_BASE_URL}/everything`,
      {
        params: {
          q: searchQuery,
          sortBy: 'publishedAt',
          language: 'en',
          pageSize: 10,
          apiKey: process.env.NEWS_API_KEY
        },
        timeout: 10000
      }
    );

    newsRequestCount++;

    // Transform articles
    const articles = response.data.articles.map((article, index) => ({
      id: `${Date.now()}-${index}`,
      title: article.title || 'No title',
      description: article.description || '',
      url: article.url,
      source: article.source.name || 'Unknown',
      publishedAt: article.publishedAt,
      imageUrl: article.urlToImage || null
    }));

    res.json({
      success: true,
      data: {
        asset: asset,
        articles: articles,
        fetchedAt: new Date().toISOString(),
        rateLimitInfo: {
          requestsUsedToday: newsRequestCount,
          requestsRemaining: 100 - newsRequestCount,
          resetTime: newsResetTime
        }
      },
      error: null
    });
  } catch (error) {
    console.error('Error fetching news:', error.message);

    if (error.response && error.response.status === 429) {
      return res.status(429).json({
        success: false,
        data: null,
        error: {
          code: 'newsapi_rate_limit_exceeded',
          message: 'NewsAPI rate limit exceeded',
          details: { error: error.message }
        }
      });
    }

    res.status(503).json({
      success: false,
      data: null,
      error: {
        code: 'external_api_unavailable',
        message: 'News data is temporarily unavailable. Please try again later.',
        details: { error: error.message }
      }
    });
  }
});

// Helper function to get full name of crypto
function getFullName(symbol) {
  const names = {
    BTC: 'Bitcoin',
    ETH: 'Ethereum',
    SOL: 'Solana',
    DOGE: 'Dogecoin',
    ADA: 'Cardano',
    DOT: 'Polkadot',
    MATIC: 'Polygon',
    LINK: 'Chainlink',
    AVAX: 'Avalanche',
    ATOM: 'Cosmos'
  };
  return names[symbol] || symbol;
}

// Health check
app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    success: false,
    data: null,
    error: {
      code: 'internal_server_error',
      message: 'An unexpected error occurred',
      details: { error: err.message }
    }
  });
});

// Start server
initializeWatchlist().then(() => {
  app.listen(PORT, () => {
    console.log(`Backend server running on http://localhost:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
});

